3	/**
4	 * Derives an owner's {@code identityKey}, the single value all duplicate detection is based on:
5	 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. Two owners are duplicates
6	 * only when their WHOLE keys are equal.
7	 *
8	 * <p>The household segment is empty for an owner not assigned to a shared household, so it never on its
9	 * own separates two owners: members of one household with different telephones already differ by the
10	 * telephone segment and are both allowed, while owners sharing a telephone and email collide.
11	 */
12	public final class OwnerIdentity {
13	
14	    private OwnerIdentity() {
15	    }
16	
17	    public static String key(String telephone, String email, String householdId) {
18	        String tel = telephone == null ? "" : telephone;
19	        String mail = email == null ? "" : email.toLowerCase();
20	        return tel + "|" + mail + "|" + (householdId == null ? "" : householdId);
21	    }
22	}
