3	/** Luhn check digit (0-9) over the digits contained in a value. */
4	public final class CheckDigit {
5	
6	    private CheckDigit() {
7	    }
8	
9	    public static int of(String value) {
10	        int sum = 0;
11	        boolean dbl = true;
12	        for (int i = value.length() - 1; i >= 0; i--) {
13	            char c = value.charAt(i);
14	            if (c < '0' || c > '9') {
15	                continue;
16	            }
17	            int d = c - '0';
18	            if (dbl) {
19	                d *= 2;
20	                if (d > 9) {
21	                    d -= 9;
22	                }
23	            }
24	            sum += d;
25	            dbl = !dbl;
26	        }
27	        return (10 - (sum % 10)) % 10;
28	    }
29	}
