3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's locality (canonical region), preferring the postcode: a four-digit
7	 * postcode within a known region range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099)
8	 * wins. When the postcode is absent or in no known range, a fixed city-to-region table
9	 * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) is used; any other city derives
10	 * {@code "UNKNOWN"}.
11	 */
12	public final class CityLocality {
13	
14	    private static final Map<String, String> CITY_REGION =
15	            Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
16	
17	    private static final Map<String, int[]> REGION_RANGE = Map.of(
18	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
19	
20	    private CityLocality() {
21	    }
22	
23	    public static String of(String city) {
24	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
25	    }
26	
27	    /** Region from the postcode range first, falling back to the city table. */
28	    public static String of(String city, String postcode) {
29	        String byPostcode = byPostcode(postcode);
30	        return byPostcode != null ? byPostcode : of(city);
31	    }
32	
33	    private static String byPostcode(String postcode) {
34	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
35	            return null;
36	        }
37	        int value = Integer.parseInt(postcode);
38	        for (Map.Entry<String, int[]> region : REGION_RANGE.entrySet()) {
39	            int[] range = region.getValue();
40	            if (value >= range[0] && value <= range[1]) {
41	                return region.getKey();
42	            }
43	        }
44	        return null;
45	    }
46	}
