3	import java.net.URI;
4	import java.time.LocalDate;
5	
6	import net.officefloor.plugin.variable.Val;
7	import net.officefloor.web.ObjectResponse;
8	import org.springframework.http.ResponseEntity;
9	import org.springframework.samples.petclinic.mapper.OwnerMapper;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.repository.OwnerRepository;
12	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
13	
14	public class RespondWithOwnerCreated {
15	
16	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
17	
18	    public void service(@Val Owner owner, OwnerMapper ownerMapper, OwnerRepository ownerRepository,
19	            ObjectResponse<ResponseEntity<OwnerDto>> response) {
20	        OwnerDto dto = ownerMapper.toOwnerDto(owner);
21	        LocalDate today = BusinessDay.roll(LocalDate.now());
22	        long createdToday = ownerRepository.findAll().stream()
23	                .filter(other -> today.equals(other.getRegistrationDate())).count();
24	        dto.setBulkSignupWarning(createdToday > 80);
25	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
26	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), dto.getMembershipLevel());
27	        response.send(ResponseEntity.created(URI.create("/api/owners/" + owner.getId())).body(dto));
28	    }
29	}
