3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
22	    @Mapping(target = "initials", expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
23	    @Mapping(target = "householdId", expression = "java(householdId(owner))")
24	    @Mapping(target = "identityKey", expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(owner.getTelephone(), owner.getEmail(), \"\"))")
25	    @Mapping(target = "checkDigit", expression = "java(owner.getCustomerCode() == null ? null : org.springframework.samples.petclinic.rest.function.owner.CheckDigit.of(owner.getCustomerCode()))")
26	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
27	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
28	    @Mapping(target = "locality", expression = "java(org.springframework.samples.petclinic.rest.function.owner.CityLocality.of(owner.getCity(), owner.getPostcode()))")
29	    @Mapping(target = "contactPreference", expression = "java(owner.getEmail() != null && !owner.getEmail().isBlank() ? \"EMAIL\" : \"PHONE\")")
30	    OwnerDto toOwnerDto(Owner owner);
31	
32	    /** Membership level set at create time: start at 1, +1 when an email is present, +1 when the
33	     *  owner has no namesakes (namesakeCount 0), capped at 3 (level 4 is reserved for tenure). */
34	    default Integer membershipLevel(Owner owner) {
35	        int level = 1;
36	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
37	            level++;
38	        }
39	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
40	            level++;
41	        }
42	        return Math.min(level, 3);
43	    }
44	
45	    /** Membership number: '<customerCode>-M<YY>', YY being the last two digits of the
46	     *  registrationDate year. Null until both source fields are assigned. */
47	    default String membershipNumber(Owner owner) {
48	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
49	            return null;
50	        }
51	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
52	    }
53	
54	    /** Stable identifier for the household an owner belongs to: same last name and address (normalized
55	     *  as in the duplicate-household guard) yield the same id, so household-sharing owners match. */
56	    default String householdId(Owner owner) {
57	        String key = normalizeHousehold(owner.getLastName()) + "|"
58	                + org.springframework.samples.petclinic.rest.function.owner.AddressNormalizer.normalize(owner.getAddress());
59	        return String.format("H-%08X", key.hashCode());
60	    }
61	
62	    private static String normalizeHousehold(String value) {
63	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
64	    }
65	
66	    Owner toOwner(OwnerDto ownerDto);
67	
68	    @Mapping(target = "id", ignore = true)
69	    @Mapping(target = "pets", ignore = true)
70	    Owner toOwner(OwnerFieldsDto ownerDto);
71	
72	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
73	
74	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
75	
76	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
77	        OwnerPageDto ownerPageDto = new OwnerPageDto();
78	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
79	        ownerPageDto.setPage(ownerPage.getNumber());
80	        ownerPageDto.setSize(ownerPage.getSize());
81	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
82	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
83	        return ownerPageDto;
84	    }
85	}
